// 3) in first rồi in sum(...rest)

solution.code:
const nums = [1, 2, 3, 4];
const [first, ...rest] = nums;

function sum(...numbers) {
  return numbers.reduce((s, n) => s + n, 0);
}

console.log(first);
console.log(sum(...rest));
